        mHdltvoutHandle << " , " <<  " \"agg_result_Packet_state\" :  \"" << agg_result_Packet_state.read() << "\" ";
        mHdltvoutHandle << " , " <<  " \"agg_result_Packet_state_ap_vld\" :  \"" << agg_result_Packet_state_ap_vld.read() << "\" ";
